def generated_loss(batch, model_output, extra):
    # Key-safe retrieval for required log-prob inputs
    if 'log_prob_w' in batch:
        lpw = batch['log_prob_w']
    elif 'log_prob_win' in batch:
        lpw = batch['log_prob_win']
    elif 'logp_w' in batch:
        lpw = batch['logp_w']
    else:
        lpw = batch['log_prob_w']

    if 'log_prob_l' in batch:
        lpl = batch['log_prob_l']
    elif 'log_prob_lose' in batch:
        lpl = batch['log_prob_lose']
    elif 'logp_l' in batch:
        lpl = batch['logp_l']
    else:
        lpl = batch['log_prob_l']

    weight = batch.get('weight', None)

    hp = extra.get('hyperparams', {}) if extra is not None else {}
    alpha = float((extra.get('alpha', None) if extra is not None else None) or hp.get('alpha', 1.0))
    scale = float(hp.get('scale', 1.0))
    beta = float(hp.get('beta', 0.1))

    cost_a = batch.get('cost_a', None)
    cost_b = batch.get('cost_b', None)
    if cost_a is None or cost_b is None:
        gap = 0.0
    else:
        gap = (cost_b - cost_a).detach()

    x = alpha * scale * (lpw - lpl) - beta * gap
    x = ops.clamp(x, -20.0, 20.0)

    # swap-symmetric average of -logsigmoid(x) and -logsigmoid(-x) simplifies to softplus(-x)
    loss = ops.softplus(-x)

    if weight is not None:
        loss = loss * weight

    return loss.mean()

